import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter} from 'react-router-dom';
import {UIProvider} from '../../src/context/UIContext.jsx';
import PhonePreview from '../../src/components/PhonePreview.jsx';
import {DUMMY_GALLERY_PHOTOS,DUMMY_GALLERY_VIDEO} from '../../src/config/dummyAssets.js';
import '../../src/styles/index.css';
import '../../src/styles/atelier.css';
import '../../src/styles/ivory-text-wash.css';
import '@fortawesome/fontawesome-free/css/all.min.css';
const photoMode=new URLSearchParams(location.search).has('photos');
const pair=photoMode?DUMMY_GALLERY_PHOTOS[0].replace('/gallery/','/gallery/./'):'/templates/ludora/assets/couple-sampul-v2.webp';
const invitation={id:'nawasena-local-audit',themeId:'nawasena',weddingDate:'2026-12-05',coupleProfile:{brideName:'Aisyah',groomName:'Auf'},themeSettings:{coverType:'custom',coverImageUrl:pair,coverSecondImageUrl:pair,typography:{fontHeading:'Cormorant Garamond',fontBody:'DM Sans',metricsMode:'template'},galleryLayout:'collage'},events:[{id:'a',type:'Akad',date:'2026-12-05',startTime:'07:30',endTime:'08:30',venueName:'Rumah Mempelai Wanita',address:'Gg. Salak, Seduri Baru, Mojosari',googleMapsUrl:'https://maps.google.com/?q=Mojosari'},{id:'r',type:'Resepsi',date:'2026-12-05',startTime:'13:00',endTime:'21:00',venueName:'Rumah Mempelai Wanita',address:'Gg. Salak, Seduri Baru, Mojosari',googleMapsUrl:'https://maps.google.com/?q=Mojosari'}],rundowns:[{id:'one',time:'08.30 – 09.30',activity:'Sesi Foto Mempelai'},{id:'two',time:'07.30 – 08.30',activity:'Akad Nikah'}],galleryMedia:[...Array.from({length:9},(_,i)=>({id:`p${i}`,type:'photo',url:DUMMY_GALLERY_PHOTOS[i%DUMMY_GALLERY_PHOTOS.length]})),{id:'v',type:'video',url:DUMMY_GALLERY_VIDEO}],invitationFeatures:{dresscodeEnabled:true,rundownEnabled:true,livestreamEnabled:true,igFilterEnabled:false,galleryEnabled:true,rsvpEnabled:true,giftEnabled:true}};
function Audit(){const [size,setSize]=useState('390,844');const [width,height]=size.split(',').map(Number);return <div style={{background:'#e8e8dd',padding:20,minHeight:'100vh'}}><aside style={{position:'fixed',left:20,top:20,display:'grid',gap:10,maxWidth:180}}><strong>Audit lokal Nawasena</strong><select aria-label="Ukuran layar" value={size} onChange={e=>setSize(e.target.value)}><option value="390,844">HP 390 × 844</option><option value="320,640">HP 320 × 640</option><option value="450,900">Panel 450 × 900</option></select>{[['cover','Hero'],['quote','Kutipan'],['profile','Mempelai'],['events','Acara'],['rundown','Rundown'],['gallery','Galeri'],['livestream','Siaran'],['rsvp','RSVP'],['footer','Penutup']].map(([section,label])=><button key={section} onClick={()=>{const root=document.querySelector('.nawasena');const el=root.querySelector(`[data-section="${section}"]`);root.scrollTo({top:root.scrollTop+el.getBoundingClientRect().top-root.getBoundingClientRect().top,behavior:'instant'});window.scrollTo({top:0,behavior:'instant'})}}>{label}</button>)}</aside><div style={{width,height,position:'relative',margin:'auto',borderRadius:24,overflow:'hidden'}}><PhonePreview invitation={invitation} editorPreview/></div></div>}
createRoot(document.getElementById('root')).render(<BrowserRouter><UIProvider><Audit/></UIProvider></BrowserRouter>);
